begin;
select no_plan();
set local statement_timeout='30s';
create function pg_temp.bid(n integer) returns uuid language sql immutable as $$select ('af260000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.actor(n integer) returns void language plpgsql as $$begin perform set_config('request.jwt.claim.sub',pg_temp.bid(n)::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.bid(n),'role','authenticated')::text,true);end$$;
insert into auth.users(id,instance_id,aud,role,email) select pg_temp.bid(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','teacher-book-'||n||'@synthetic.invalid' from generate_series(1,5)n;
insert into public.profiles(id,role,name,email) select pg_temp.bid(n),case n when 1 then 'admin' when 2 then 'staff' when 3 then 'teacher' when 4 then 'assistant' else 'viewer' end,'공통 담당자 '||n,'PRIVATE_ACCOUNT_CANARY'||n||'@synthetic.invalid' from generate_series(1,5)n on conflict(id) do update set role=excluded.role,name=excluded.name,email=excluded.email;
select pg_temp.actor(1);
insert into public.textbook_inventory_locations(id,code,name,sort_order) values(pg_temp.bid(900),'teacher_common_book','본관',10);
insert into public.classes(id,name,class_type,subject,status,student_ids,waitlist_ids,textbook_ids,lessons,schedule_plan) values(pg_temp.bid(101),'공통 교재 수업','정규','영어','수강','[]','[]','[]','[]','{}');
insert into public.textbooks(id,title,name,subject,publisher,category,isbn13,price,sale_price,school_level,grade_level,school_levels,grade_levels,sub_subject,status)
select pg_temp.bid(200+n),'공통 교재 '||n,'공통 교재 '||n,'english','공통 출판사','독해','teacher-common-'||n,123456,123456,'middle','m2',array['middle'],array['m2'],'독해','active' from generate_series(1,16)n;
insert into public.textbook_purchase_orders(id,requested_by,order_date,status,created_by,created_at,memo)
select pg_temp.bid(300+n),'공통 담당자 2',date '2026-10-01','requested',pg_temp.bid(2),'2026-10-01T00:00:00Z','PRIVATE_MEMO_CANARY' from generate_series(1,16)n;
insert into public.textbook_purchase_order_lines(id,purchase_order_id,textbook_id,class_id,location_id,requested_quantity,copy_scope,created_at)
select pg_temp.bid(400+n),pg_temp.bid(300+n),pg_temp.bid(200+n),pg_temp.bid(101),pg_temp.bid(900),2,'student','2026-10-01T00:00:00Z' from generate_series(1,16)n;
create function pg_temp.page(n integer default 1,s text default '') returns jsonb language sql as $$select public.read_operational_common_v1('book_page',jsonb_build_object('p_search',s,'p_page',n,'p_page_size',15))$$;
insert into public.textbook_suppliers(id,name,memo) values(pg_temp.bid(990),'거래처','PRIVATE_SUPPLIER_CANARY');
select pg_temp.actor(3);set local role authenticated;
select is((pg_temp.page()->>'totalCount')::integer,16,'teacher sees all unrelated common requests');
select is(jsonb_array_length(pg_temp.page()->'rows'),15,'common request page preserves page size');
select is(jsonb_array_length(pg_temp.page(2)->'rows'),1,'common request second page has remaining row');
select ok(pg_temp.page()::text not like '%PRIVATE_%','positive request DTO excludes private memo/account');
select ok(pg_temp.page()::text not like '%123456%','request common DTO has no purchase price');
select is((pg_temp.page(1,'공통 교재 16')->>'totalCount')::integer,1,'safe common title search counts before pagination');
select is((pg_temp.page(1,'PRIVATE_MEMO_CANARY')->>'totalCount')::integer,0,'private memo cannot be inferred via request search');
select is((pg_temp.page(1,'PRIVATE_ACCOUNT_CANARY')->>'totalCount')::integer,0,'private account is not a requester search fallback');
select ok(not exists(select 1 from jsonb_array_elements(pg_temp.page()->'rows')r where (select count(*) from jsonb_object_keys(r))<>8),'common row exact eight-field projection');
select is((select count(*) from public.textbook_purchase_orders),0::bigint,'teacher cannot directly read original order');
select is((select count(*) from public.textbook_purchase_order_lines),0::bigint,'teacher cannot directly read original line');
select throws_ok($q$select public.list_textbook_purchase_page_v1('{"mode":"request","search":"","boardScope":"all","requestFilter":"all","orderFilter":"all"}','status-event',1,15)$q$,'42501','operational_common_read_required','legacy full request page is not teacher fallback');
select throws_ok($q$select public.get_textbook_purchase_detail_v1(pg_temp.bid(401),'request')$q$,'42501','operational_common_read_required','legacy private request detail is closed to teacher');
select throws_ok($q$select public.get_textbook_purchase_summary_v1('{"mode":"request","search":"","boardScope":"all","requestFilter":"all","orderFilter":"all"}')$q$,'42501','operational_common_read_required','legacy financial summary is closed to teacher');
select is(public.read_operational_common_v1('book_detail',jsonb_build_object('p_anchor',pg_temp.bid(416)))->>'bookTitle','공통 교재 16','off-page deep link uses same safe common DTO');
select is(public.read_operational_common_v1('book_detail',jsonb_build_object('p_anchor',pg_temp.bid(999))),null::jsonb,'missing common detail does not return arbitrary row');
select is((select count(*) from public.textbook_suppliers where id=pg_temp.bid(990)),0::bigint,'teacher cannot directly read supplier memo');
select ok(exists(select 1 from pg_policies where schemaname='public' and tablename=t and policyname=t||'_teacher_private_read_v1' and permissive='RESTRICTIVE' and cmd='SELECT'),'management raw read fence present: '||t) from unnest(array['textbook_suppliers','textbook_makeedu_payment_imports','textbook_monthly_closings','textbook_sales','textbook_sale_lines','textbook_stock_moves','textbook_stock_counts','textbook_supplier_links','textbook_publisher_supplier_links'])t;
select diag('TEACHER_BOOK_CAPTURE='||pg_temp.page()::text);
reset role;
select pg_temp.actor(2);set local role authenticated;
select lives_ok($q$select public.list_textbook_purchase_page_v1('{"mode":"request","search":"","boardScope":"all","requestFilter":"all","orderFilter":"all"}','status-event',1,15)$q$,'staff original processing page remains available');
select is((select count(*) from public.textbook_purchase_orders),16::bigint,'staff retains raw management access');
select throws_ok($q$select pg_temp.page()$q$,'42501','operational_common_read_forbidden','manager does not impersonate teacher gateway');
reset role;
select pg_temp.actor(4);set local role authenticated;
select throws_ok($q$select pg_temp.page()$q$,'42501','operational_common_read_forbidden','assistant cannot reach teacher book source');
reset role;
select pg_temp.actor(5);set local role authenticated;
select throws_ok($q$select pg_temp.page()$q$,'42501','operational_common_read_forbidden','viewer scope remains unchanged');
reset role;
select * from finish();rollback;
